{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Perindoprilat, the active diacid of the ACE inhibitor prodrug perindopril, had 30±6% oral bioavailability in cirrhotic patients, directly exceeding the 20% threshold and supporting high F for the query fosinopril, a related ACE inhibitor prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Perindopril, an ACE inhibitor ethyl ester prodrug, showed 66–95% absolute oral bioavailability in healthy/hypertensive subjects under fasting conditions, providing strong supportive evidence for high F in the analogous prodrug fosinopril.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Encainide in cirrhotic patients had 76±17% oral bioavailability, adding supportive evidence that even with hepatic impairment, F can be well above 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Praziquantel in patients with hepatic cirrhosis had 27.2±5.4% oral bioavailability, another example of F≥20% in a lipophilic, moderately polar drug, supporting the high prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is fosinopril, a phosphinic acid ACE inhibitor prodrug. The closest transferable evidence comes from perindoprilat (30% F in cirrhosis) and perindopril (66–95% F in healthy/hypertensive subjects), both ACE inhibitor-related molecules with high transfer scores. These direct experimental measurements strongly support F≥20%. Additional high-F analogues (encainide, praziquantel) reinforce the pattern. The only low-F evidence, ipratropium, is a permanently charged quaternary ammonium with negligible transfer to the query and does not outweigh the supportive ACE inhibitor data. The physicochemical prior is mixed/unfavorable, but direct experimental evidence from close analogues overrides it.",
  "evidence_gaps": [
    "No direct fosinopril bioavailability measurement is provided; prediction relies on close ACE inhibitor analogues.",
    "Most supportive data are from patients with cirrhosis or hepatic disease, though perindopril in healthy subjects was 66–95%.",
    "The query's high molecular weight, TPSA, and anionic character create residual uncertainty, but the experimental analogues are decisive."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C21"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "ACE inhibitor diacid"
    },
    {
      "applicability": "high",
      "card_ids": ["C03"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "ACE inhibitor prodrug"
    },
    {
      "applicability": "low",
      "card_ids": ["C02"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "quaternary ammonium anticholinergic"
    }
  ],
  "revision_action": "initial"
}

